/**
 * AiSnapshotService.js
 *
 * Fetches the lightweight hourly BTCUSDT AI + On-Chain JSON generated by GitHub Actions
 * from the isolated `ai-snapshot` branch (zero Vercel rebuilds), with automatic fallback
 * to `/ai_oracle_snapshot.json` served statically from `public/`.
 */

const GITHUB_RAW_SNAPSHOT_URL =
  'https://raw.githubusercontent.com/agentetecnova/BOT-TRADING/ai-snapshot/ai_oracle_snapshot.json';
const LOCAL_FALLBACK_URL = '/ai_oracle_snapshot.json';

class AiSnapshotService {
  async fetchLatestSnapshot() {
    // Bust GitHub Raw CDN safely on a 5-minute bucket
    const cacheBucket = Math.floor(Date.now() / 300000);
    const urls = [
      `${GITHUB_RAW_SNAPSHOT_URL}?t=${cacheBucket}`,
      `${LOCAL_FALLBACK_URL}?t=${cacheBucket}`
    ];

    for (const url of urls) {
      try {
        const res = await fetch(url, { cache: 'no-store' });
        if (!res.ok) continue;
        const data = await res.json();
        if (data && data.horizons) {
          return {
            ...data,
            sourceUrl: url.includes('githubusercontent') ? 'github-hourly' : 'local-fallback'
          };
        }
      } catch {
        // Try next fallback URL cleanly
      }
    }
    return null;
  }
}

const aiSnapshotService = new AiSnapshotService();
export default aiSnapshotService;
